<?php if(session_status()===PHP_SESSION_NONE){session_name('ITEMA');session_start();}if(!isset($_SESSION['name'])){http_response_code(401);exit;}ob_start();include('head.php');ob_end_clean();$h=(int)date('H');$window=$h>=7&&$h<15?'s1':($h>=15&&$h<23?'s2':'s3');$date=date('Y-m-d');if($window==='s3'&&$h<7)$date=date('Y-m-d',strtotime('-1 day'));
$rows=$db->exec("SELECT t.IdTelaio id,t.NomeTelaio name,t.Online online,r.Timestamp lastUpdate,r.Velocita rpm,r.Resa efficiency,r.Armatura1 pattern,r.Warnings warnings,COALESCE(s.StopCount,0) stopCount,COALESCE(s.StopSeconds,0) stopSeconds,CASE WHEN r.Timestamp IS NULL THEN NULL ELSE TIMESTAMPDIFF(SECOND,r.Timestamp,NOW()) END age FROM telaio t LEFT JOIN dato_rt r ON r.IdTelaio=t.IdTelaio LEFT JOIN loom_stop_window_summary s ON s.LoomId=t.IdTelaio AND s.SummaryDate=? AND s.WindowCode=? WHERE t.EnableTelaio=1 AND t.IdTelaio<>100 ORDER BY t.IdTelaio",array(1=>$date,2=>$window));foreach($rows as &$r){$r['id']=(int)$r['id'];$r['age']=$r['age']===null?null:(int)$r['age'];$r['stopCount']=(int)$r['stopCount'];$r['stopSeconds']=(int)$r['stopSeconds'];$r['status']=((int)$r['online']!==1||$r['age']===null||$r['age']>60)?'offline':((int)$r['rpm']>0?'running':'stopped');}$out=array('window'=>$window,'rows'=>$rows);header('Content-Type: application/json;charset=utf-8');echo json_encode($out,JSON_UNESCAPED_UNICODE);
